export class SeaAudio{
 constructor(){this.context=null;this.enabled=true;this.timer=0;this.note=0;this.master=null;}
 async unlock(){if(!this.context){const Audio=globalThis.AudioContext||globalThis.webkitAudioContext;if(!Audio)return;try{this.context=new Audio();this.master=this.context.createGain();this.master.gain.value=.34;this.master.connect(this.context.destination);}catch{return;}}if(this.context.state==='suspended')try{await this.context.resume();}catch{}}
 setEnabled(value){this.enabled=value;if(this.context&&this.master)this.master.gain.setTargetAtTime(value?.34:0,this.context.currentTime,.08);}
 tone(freq,duration=.6,volume=.13,type='sine',delay=0){const a=this.context;if(!a||a.state!=='running'||!this.enabled)return;const at=a.currentTime+delay,osc=a.createOscillator(),gain=a.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,at);gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(volume,at+.025);gain.gain.exponentialRampToValueAtTime(.0001,at+duration);osc.connect(gain);gain.connect(this.master);osc.start(at);osc.stop(at+duration+.03);osc.onended=()=>{osc.disconnect();gain.disconnect();};}
 play(event){if(event.type==='launch'){this.tone(196,.32,.06);this.tone(294,.5,.025,'sine',.05);}if(event.type==='light'){const f=[392,440,523.25,587.33][event.index%4];this.tone(f,1,.16);this.tone(f*2,1.2,.045,'sine',.05);}if(event.type==='tear')this.tone(98,.7,.08,'triangle');if(event.type==='return')this.tone(261.63,.8,.05);if(event.type==='weave')[220,329.63,440,659.25].forEach((f,i)=>this.tone(f,2.8,.075,'sine',i*.16));if(event.type==='open'||event.type==='clear')[261.63,329.63,392,523.25].forEach((f,i)=>this.tone(f,event.type==='clear'?2.4:1.5,.09,'sine',i*.13));}
 update(dt,playing=true){if(!playing||!this.enabled||!this.context||this.context.state!=='running')return;this.timer-=dt;if(this.timer<=0){const melody=[196,0,293.66,261.63,0,329.63,293.66,0,220,0,261.63,0,392,329.63,0,293.66];const f=melody[this.note++%melody.length];if(f){this.tone(f,2.5,.035);this.tone(f/2,3.8,.025);}this.timer=1.4;}}
 suspend(){if(this.context?.state==='running')this.context.suspend().catch(()=>{});}
}
